"""Artifact-only physical-window SQL correctness/latency driver, including genuine duplicate calls.

Do not time while any build/test/resource task is active. Native window
partitions and their stage sorting remain unbounded; work_mem here also
affects any ordinary final TypedSort, not a claimed WindowAgg memory cap.
"""
import argparse,csv,hashlib,json,random,shutil,statistics,sys,time
from pathlib import Path
REPO=Path(__file__).resolve().parents[2];sys.path.insert(0,str(REPO/'scripts'))
import benchmark_queries as query

def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def tree(root):return {str(p.relative_to(root)):sha(p) for p in sorted(root.rglob('*')) if p.is_file()}
def digest(rows):return hashlib.sha256(json.dumps(rows,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()

def specifications(size=1000):
    ids=list(range(1,size+1));partitions={group:[i for i in ids if i%100==group] for group in range(100)}
    positions={i:index for group in partitions.values() for index,i in enumerate(group)}
    clause='PARTITION BY grp ORDER BY id';prefix=clause+' ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW'
    full=clause+' ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING'
    rows=lambda callback:[[str(i),*callback(i,partitions[i%100],positions[i])] for i in ids]
    result = {
        'partition_ranking':{'sql':'SELECT id,row_number() OVER('+clause+') AS rn,rank() OVER('+clause+') AS rk,dense_rank() OVER('+clause+') AS dr FROM bench_rows ORDER BY id',
                             'expected':rows(lambda i,p,j:[str(j+1)]*3)},
        'partition_lag':{'sql':'SELECT id,lag(amount) OVER('+clause+') AS v FROM bench_rows ORDER BY id',
                         'expected':rows(lambda i,p,j:[str(p[j-1]%1000) if j else None])},
        'partition_lead':{'sql':'SELECT id,lead(amount) OVER('+clause+') AS v FROM bench_rows ORDER BY id',
                          'expected':rows(lambda i,p,j:[str(p[j+1]%1000) if j+1<len(p) else None])},
        'running_sum':{'sql':'SELECT id,sum(amount) OVER('+prefix+') AS v FROM bench_rows ORDER BY id',
                       'expected':rows(lambda i,p,j:[str(sum(k%1000 for k in p[:j+1]))])},
        'sliding_sum':{'sql':'SELECT id,sum(amount) OVER('+clause+' ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS v FROM bench_rows ORDER BY id',
                       'expected':rows(lambda i,p,j:[str(sum(k%1000 for k in p[max(0,j-2):j+1]))])},
        'partition_full_sum':{'sql':'SELECT id,sum(amount) OVER(PARTITION BY grp) AS v FROM bench_rows ORDER BY id',
                              'expected':rows(lambda i,p,j:[str(sum(k%1000 for k in p))])},
        'full_first_last_nth':{'sql':'SELECT id,first_value(amount) OVER('+full+') AS f,last_value(amount) OVER('+full+') AS l,nth_value(amount,2) OVER('+full+') AS n FROM bench_rows ORDER BY id',
                              'expected':rows(lambda i,p,j:[str(p[0]%1000),str(p[-1]%1000),str(p[1]%1000) if len(p)>1 else None])},
        'mixed_same_keys':{'sql':'SELECT id,row_number() OVER('+clause+') AS rn,lag(amount) OVER('+clause+') AS prev,sum(amount) OVER('+prefix+') AS running FROM bench_rows ORDER BY id',
                           'expected':rows(lambda i,p,j:[str(j+1),str(p[j-1]%1000) if j else None,str(sum(k%1000 for k in p[:j+1]))])},

    }
    for copies in (1,2,4):
        call='lag(length(payload),0) OVER('+clause+')'
        result['length_lag_'+str(copies)]={
            'sql':'SELECT id,'+','.join(call+' AS v'+str(index) for index in range(copies))+' FROM bench_rows ORDER BY id',
            'expected':rows(lambda i,p,j:[str(len('row-'+str(i)))]*copies)}
    call='sum(amount) OVER('+prefix+')'
    result['duplicate_running_sum']={
        'sql':'SELECT id,'+call+' AS a,'+call+' AS b FROM bench_rows ORDER BY id',
        'expected':rows(lambda i,p,j:[str(sum(k%1000 for k in p[:j+1]))]*2)}
    return result

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    for name in ['before','after','fixture','output']:parser.add_argument('--'+name,required=True,type=Path)
    parser.add_argument('--work-mem',required=True,choices=['64kB','4MB','16MB'])
    parser.add_argument('--rows',type=int,default=1000);parser.add_argument('--rounds',type=int,default=3);parser.add_argument('--samples',type=int,default=4)
    parser.add_argument('--validate-only',action='store_true');args=parser.parse_args()
    if args.rows!=1000 or args.rounds!=3 or args.samples!=4:parser.error('frozen1000rows/3rounds/4samples required')
    output=args.output.resolve();output.mkdir(parents=True,exist_ok=False);fixture=args.fixture.resolve();original=tree(fixture);specs=specifications(args.rows)
    (output/'fixed-specifications.json').write_text(json.dumps(specs,ensure_ascii=False,indent=2)+'\n')
    report={'complete':False,'validation_only':args.validate_only,'driver_sha256':sha(__file__),'work_mem':args.work_mem,'rows':1000,
            'rounds':3,'samples_per_case_per_label':12,'fixture_hashes':original,'runs':[],
            'method':'Original common8 plus4 fixed duplicate/length cases, separate old/new/old fixture copies, independent Python integer/partition/frame/full-row oracle. Timing is start -> query/parse/wire -> complete equality -> stop. Three warmups and12 samples/case; all raw returned rows in JSONL, all samples and slow values retained. Evidence writes excluded. Session work_mem SET/SHOW checked. No processCPU/RSS/cold-cache/general-speedup claim. Window partitions/stage sorts are currently unbounded; this does not finish OPT10.'}
    destination=output/'comparison.json'
    def save():destination.write_text(json.dumps(report,indent=2)+'\n')
    try:
        for label,binary in [('old-first',args.before.resolve()),('new',args.after.resolve()),('old-last',args.before.resolve())]:
            data=output/label;shutil.copytree(fixture,data)
            run={'label':label,'binary_sha256':sha(binary),'samples':[],'warmups':[],'validations':[]};report['runs'].append(run);save()
            with (output/(label+'-rows.jsonl')).open('w') as raw,(output/(label+'-samples.csv')).open('w',newline='') as samples_csv,query.server(binary,data,output/(label+'.log')) as(client,_,_):
                writer=csv.writer(samples_csv);writer.writerow(['case','phase','index','latency_ms','rows','cells','validated','rows_sha256'])
                client.sock.settimeout(15);assert client.query("SET work_mem='"+args.work_mem+"'")==[];assert client.query('SHOW work_mem')==[[args.work_mem]]
                def execute(name,index,phase):
                    case=specs[name];start=time.perf_counter() if phase=='sample' else None
                    actual=client.query(case['sql']);valid=actual==case['expected']
                    elapsed=(time.perf_counter()-start)*1000 if start is not None else None
                    item={'name':name,'index':index,'phase':phase,'validated':valid,'rows':len(actual),'cells':sum(map(len,actual)),'sha256':digest(actual)}
                    if elapsed is not None:item['latency_ms']=elapsed
                    raw.write(json.dumps({**item,'actual':actual},ensure_ascii=False)+'\n');raw.flush()
                    writer.writerow([name,phase,index,elapsed if elapsed is not None else '',item['rows'],item['cells'],valid,item['sha256']]);samples_csv.flush()
                    run[{'sample':'samples','warmup':'warmups','validation':'validations'}[phase]].append(item)
                    if not valid:run['failure']={'name':name,'actual':actual,'expected':case['expected']};save();raise AssertionError('full value mismatch: '+name)
                if args.validate_only:
                    for name in specs:execute(name,0,'validation')
                else:
                    for name in specs:
                        for i in range(3):execute(name,i,'warmup')
                    for round_index in range(3):
                        order=list(specs);random.Random(20261102+round_index).shuffle(order)
                        for name in order:
                            for index in range(4):execute(name,round_index*4+index,'sample')
            if not args.validate_only:run['summaries']=[{'name':name,'samples':12,'p50_ms':statistics.median(x['latency_ms'] for x in run['samples'] if x['name']==name)} for name in specs]
            print(label,'validated',len(run['validations']),'timed',len(run['samples']),flush=True);save()
        report['source_fixture_unchanged']=tree(fixture)==original;assert report['source_fixture_unchanged'];report['complete']=True
    except BaseException as error:report['error']=repr(error);raise
    finally:save()

if __name__=='__main__':main()

"""Actual window host and optional ordinary final TypedSort resources; no timing."""
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import socket
import sys
import threading
import time

REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO / "scripts"))
import benchmark_queries as query


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def tree(root):
    return {str(path.relative_to(root)): sha(path) for path in sorted(root.rglob("*")) if path.is_file()}


def row_digest(rows):
    return hashlib.sha256(json.dumps(rows, ensure_ascii=False, separators=(",", ":")).encode()).hexdigest()


def owner(pid, binary, data):
    process = Path(f"/proc/{pid}")
    command = (process / "cmdline").read_bytes().split(b"\0")
    assert (process / "exe").resolve() == binary
    assert b"--server" in command and b"--data-dir" in command
    assert command[command.index(b"--data-dir") + 1] == str(data).encode()
    return {"pid": pid, "start_ticks": int((process / "stat").read_text().rsplit(")", 1)[1].split()[19]),
            "exe": str(binary), "data": str(data), "command": [part.decode() for part in command if part]}


def files(pid):
    result = {}
    for entry in Path(f"/proc/{pid}/fd").iterdir():
        try:
            target = str(entry.readlink())
            if "/.dbms-sort-" in target:
                result[entry.name] = target
        except FileNotFoundError:
            pass
    return result


def owned_sort_target(target, data):
    suffix = " (deleted)"
    path = Path(target[:-len(suffix)] if target.endswith(suffix) else target)
    return path.parent == data and path.name.startswith(".dbms-sort-")


def named_transitions(pid, observed):
    """Resolve every sampled mkstemp/unlink window using actual FD evidence."""
    transitions = []
    for index, sample in enumerate(observed):
        for fd, target in sample.items():
            if target.endswith(" (deleted)"):
                continue
            item = {"named_snapshot": index, "fd": fd, "path": target}
            later = next((following for following in range(index + 1, len(observed))
                          if observed[following].get(fd) == target + " (deleted)"), None)
            if later is not None:
                item.update({"resolution": "same_fd_path_deleted", "deleted_snapshot": later, "resolved": True})
            else:
                # readlink, rather than exists(), distinguishes an actual
                # closed FD from an open descriptor to an unlinked file.
                try:
                    final_target = str(Path(f"/proc/{pid}/fd/{fd}").readlink())
                except FileNotFoundError:
                    final_target = None
                path_exists = Path(target).exists()
                item.update({"resolution": "post_query_fd_closed_and_path_absent",
                             "post_query_fd_target": final_target, "post_query_path_exists": path_exists,
                             "resolved": final_target is None and not path_exists})
            transitions.append(item)
    return transitions


def specifications():
    repeat=512
    ordered=sorted(range(1,1001),key=lambda i:(("row-"+str(i))*repeat).encode(),reverse=True)
    sql="SELECT id,repeat(payload,512) AS wide,row_number() OVER(ORDER BY id) AS rn FROM bench_rows ORDER BY wide DESC,id"
    expected=[[str(i),("row-"+str(i))*repeat,str(i)] for i in ordered]
    return [dict(name="ordinary_final_typed_sort_low",work_mem="64kB",expected_spill=True,sql=sql,expected=expected,branches=["one real physical window source; only ordinary final TypedSort may spill"]),
            dict(name="ordinary_final_typed_sort_high",work_mem="16MB",expected_spill=None,sql=sql,expected=expected,branches=["window partition/stage sort memory is not governed by work_mem; final sort budget only"])]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--binary", required=True, type=Path)
    parser.add_argument("--fixture", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    binary, fixture, output = args.binary.resolve(), args.fixture.resolve(), args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    data = output / "data"; original = tree(fixture); shutil.copytree(fixture, data)
    result = {"complete": False, "binary_sha256": sha(binary), "driver_sha256": sha(__file__),
              "benchmark_queries_sha256": sha(REPO / "scripts/benchmark_queries.py"),
              "fixture_hashes": original, "controls": [], "failures": 0,
              "scope": "Owned actual Main physical window plus ordinary final TypedSort anonymous FDs/full values/cleanup. Window partition and stage-sort buffers remain unbounded and are not governed by work_mem. No OPT10 completion claim. "
                       "Each sampled named mkstemp path must later be deleted on the same FD/path or have actual closed-FD/absent-path proof. "
                       "Spill still requires sampled deleted-FD evidence. No branch sorts; default durability, socket15s/TCP_NODELAY. "
                       "No latency or full-query RSS claim."}
    try:
        with query.server(binary, data, output / "server.log") as (client, pid, _):
            client.sock.settimeout(15); result["owner"] = owner(pid, binary, data)
            for spec in specifications():
                item = {key: value for key, value in spec.items() if key != "expected"}
                wanted = spec["expected"]; response = {}; observed = []
                item.update({"expected_rows": len(wanted), "expected_cells": sum(map(len, wanted)),
                             "expected_sha256": row_digest(wanted)})
                try:
                    item["set_result"] = client.query("SET work_mem='" + spec["work_mem"] + "'")
                    item["show_result"] = client.query("SHOW work_mem")
                    assert item["set_result"] == [] and item["show_result"] == [[spec["work_mem"]]]
                    def request():
                        try:
                            response["rows"] = client.query(spec["sql"])
                        except BaseException as error:
                            response["error"] = repr(error)
                    worker = threading.Thread(target=request); worker.start(); deadline = time.monotonic() + 16
                    while worker.is_alive() and time.monotonic() < deadline:
                        current = files(pid)
                        if current and (not observed or current != observed[-1]):
                            observed.append(current)
                        time.sleep(.0001)
                    if worker.is_alive():
                        client.sock.shutdown(socket.SHUT_RDWR)
                    worker.join(timeout=2); assert not worker.is_alive(), "private probe worker did not stop"
                    remaining = files(pid)
                    saw_anonymous = any(target.endswith(" (deleted)") for sample in observed for target in sample.values())
                    owned_targets = all(owned_sort_target(target, data) for sample in observed for target in sample.values())
                    transitions = named_transitions(pid, observed)
                    transitions_complete = all(item["resolved"] for item in transitions)
                    item.update({"observed": observed, "saw_anonymous": saw_anonymous,
                                 "owned_sort_targets": owned_targets, "named_fd_transitions": transitions,
                                 "named_fd_transitions_complete": transitions_complete, "remaining": remaining,
                                 "named_temporary_files": [str(path) for path in data.glob(".dbms-sort-*")],
                                 "rows": len(response.get("rows", [])),
                                 "actual_sha256": row_digest(response["rows"]) if "rows" in response else None,
                                 "values_validated": response.get("rows") == wanted, "error": response.get("error")})
                    item["passed"] = (item["values_validated"] and "error" not in response and
                                      (spec["expected_spill"] is None or saw_anonymous == spec["expected_spill"]) and owned_targets and transitions_complete and not remaining and
                                      not item["named_temporary_files"] and all(len(sample) <= 2 for sample in observed))
                    if not item["values_validated"]:
                        (output / (spec["name"] + "-value-mismatch.json")).write_text(
                            json.dumps({"sql": spec["sql"], "expected": wanted, "response": response},
                                       ensure_ascii=False, indent=2) + "\n")
                except BaseException as error:
                    item["passed"] = False; item["probe_error"] = repr(error)
                result["controls"].append(item); result["failures"] += not item["passed"]
                print(json.dumps(item), flush=True)
                (output / "result.json").write_text(json.dumps(result, indent=2) + "\n")
        result["source_fixture_unchanged"] = tree(fixture) == original
        assert result["source_fixture_unchanged"]
        result["complete"] = True
    except BaseException as error:
        result["error"] = repr(error); raise
    finally:
        (output / "result.json").write_text(json.dumps(result, indent=2) + "\n")
    print("MAIN_WINDOW_RESOURCE_COMPLETE", len(result["controls"]), "FAILURES", result["failures"], flush=True)
    assert len(result["controls"]) == 2 and not result["failures"]


if __name__ == "__main__":
    main()

