    if(owning && !OwningHelper<Helper>::available){std::cout<<"PRIMITIVE_UNAVAILABLE N="<<n<<" API=legacy_helper_owning_capture\n";return;}
    // Actual row values from the already-executed physical cursor, never a
    // rendered row parse. Each helper expression is evaluated exactly once.
    std::map<std::string,std::string> hints;for(const auto& c:descriptor)hints[c.name]=c.type;
    const auto m=measured([&]{for(size_t r=0;r<rows.size();++r){std::map<std::string,std::string> values;std::set<std::string> nulls;for(size_t c=0;c<3;++c){values[descriptor[c].name]=rows[r][c].value;if(rows[r][c].isNull)nulls.insert(descriptor[c].name);}for(size_t c=0;c<3;++c){const auto want=expected(r+1,c);ExprEvalResult result;if(owning){if constexpr(OwningHelper<Helper>::available)result=OwningHelper<Helper>::call(descriptor[c].name,values,nulls,hints,db);}else result=Helper::evalStringWithNulls(descriptor[c].name,values,nulls,hints,db,"admin",&g_engine);require(result.ok && result.typeName==descriptor[c].type && result.isNull==!want && (!want || result.value==*want),"actual helper once result");if(owning){if constexpr(OwningHelper<Helper>::available)require(OwningHelper<Helper>::valid(result,want),"actual helper owning result");}}}});
