    std::vector<PgColumnDescription> columns;bool allMetadata=true;auto cat=g_engine.catalogService().acquire(db);
    print("wire_columns_actual_descriptor",n,0,measured([&]{for(const auto& out:descriptor){const auto type=cat->getType(out.typeOid);require(bool(type),"actual type catalog row");PgColumnDescription col;col.name=out.name;col.typeOid=out.typeOid;col.typeSize=type->typlen;col.typeModifier=out.typeMod;col.formatCode=binary;allMetadata=CopyMetadata<QueryOutputColumn,PgColumnDescription>::copy(out,col,metadata) && allMetadata;columns.push_back(std::move(col));}}),"owning="+std::to_string(owning)+" format="+std::to_string(binary)+" metadata_requested="+std::to_string(metadata));
    int fds[2];require(!socketpair(AF_UNIX,SOCK_STREAM,0,fds),"socketpair");SecureSocket sender(fds[0]),receiver(fds[1]);timeval timeout{2,0};require(!setsockopt(receiver.fd,SOL_SOCKET,SO_RCVTIMEO,&timeout,sizeof(timeout)),"recv timeout");PostgresProtocol protocol(sender);
