void run(const std::string& db,size_t n) {
    const auto table="primitive_n"+std::to_string(n);const std::string sql="SELECT id,i,t FROM "+table+" ORDER BY id";
    std::shared_ptr<PreparedQuery> query;std::shared_ptr<PreparedQueryExecution> execution;std::unique_ptr<PreparedQueryCursor> cursor;
    print("prepare_bound_query",n,0,measured([&]{query=std::make_shared<PreparedQuery>(g_engine.prepareBoundQuery(db,sql));}));
    print("actual_owner_root_constant_planning",n,0,measured([&]{execution=std::make_shared<PreparedQueryExecution>(query,&g_engine,db);execution->planStatementConstants(query->ast.get());}));
    print("build_actual_graph_cursor",n,0,measured([&]{auto plan=QueryPlanner::buildPreparedQueryPlan(&g_engine,db,query,query->ast.get(),{},[&execution]{return execution;});cursor=QueryPlanner::makePreparedCursor(std::move(plan),query->output);}));
    require(cursor->descriptor().size()==3 && cursor->descriptor()[0].typeOid==23 && cursor->descriptor()[1].typeOid==23 && cursor->descriptor()[2].typeOid==25,"actual primitive descriptor");require(cursor->supportsRestart(),"real cursor restart");const auto* root=cursor->plan();const auto nodes=graph(cursor->plan());const auto originalSource=query->source;Rows first;Row row;
    // The source is verified while the actual graph is still unopened. A
    // materializing sort may legitimately close its heap before first output.
    const PreparedQuery::SourceRange* source=nullptr;
    for(const auto& range:query->sourceRanges)if(range.owner==query->ast.get() && range.relationName==table) {
        require(!source,"one actual physical source range");source=&range;
    }
    require(source && source->source && source->columns.size()==3,"genuine bound source");
    auto catalog=g_engine.catalogService().acquire(db);const auto* ns=catalog->findNamespaceByName(source->relationSchema);
    require(ns,"actual source namespace");const auto relation=catalog->getClassByName(source->relationName,ns->oid);
    require(bool(relation),"actual source relation");auto attributes=catalog->findAttributesByNum(relation->oid);
    attributes.erase(std::remove_if(attributes.begin(),attributes.end(),[](const auto& a){return a.attnum<=0 || a.attisdropped;}),attributes.end());
    require(attributes.size()==3,"actual source attributes");
    for(size_t i=0;i<3;++i)require(source->columns[i].name==attributes[i].attname &&
        source->columns[i].typeOid==attributes[i].atttypid && query->output[i].typeOid==attributes[i].atttypid,"actual bound/catalog primitive descriptor");
    TableScanOp* heap=nullptr;
    for(auto* node:nodes)if(auto* scan=dynamic_cast<TableScanOp*>(node)){require(!heap,"one actual heap scan");heap=scan;}
    require(heap && heap->tableName()==source->relationName,"actual physical graph source");
    const auto pureOrigin=heap->scanOrigin();
    require(pureOrigin.engine==&g_engine && pureOrigin.dbname==db && pureOrigin.tablename==table &&
        heap->runtimeRows()==0 && heap->runtimeLoops()==0,"unopened genuine source identity");
    for(size_t invocation=0;invocation<4;++invocation){Rows rows;if(invocation){print("new_actual_owner_root_constant_planning",n,invocation,measured([&]{execution=std::make_shared<PreparedQueryExecution>(query,&g_engine,db);execution->planStatementConstants(query->ast.get());}));print("same_graph_restart",n,invocation,measured([&]{cursor->restart(execution->context());}));}
        bool got=false;print("first_next_including_lazy_open",n,invocation,measured([&]{got=cursor->next(row);if(n){require(got,"first row");validate(row,1);rows.push_back(row);}else require(!got,"zero rows");}));
        // Record the real observed RID, including a legitimate reset after
        // buffering/close. Bound catalog+actual graph identity above provides
        // the provenance proof; no invented nonzero RID is required here.
        const auto observedOrigin=heap->scanOrigin();
        require(observedOrigin.engine==pureOrigin.engine && observedOrigin.dbname==pureOrigin.dbname &&
            observedOrigin.tablename==pureOrigin.tablename,"physical source identity retained");
        std::cout<<"PRIMITIVE_FIRST_ORIGIN N="<<n<<" invocation="<<invocation<<" table="<<observedOrigin.tablename
            <<" rid_observed="<<observedOrigin.rid<<" heap_rows_cumulative="<<heap->runtimeRows()<<" bound_catalog_and_graph_verified=true\n";
        if(n){print("remaining_next_value_copy_validation",n,invocation,measured([&]{for(size_t id=2;id<=n;++id){require(cursor->next(row),"earlyEOF");validate(row,id);rows.push_back(row);}}));print("EOF_next_including_automatic_close",n,invocation,measured([&]{require(!cursor->next(row),"excess row");}));}
        print("explicit_close_and_actual_child_cleanup",n,invocation,measured([&]{cursor->close();cursor->close();execution->closeChildCursors();}));require(cursor->plan()==root && graph(cursor->plan())==nodes && query->source==originalSource && query->parameters.empty(),"actual graph/source/frame changed");require(rows.size()==n && StorageEngine::captureNullRowBinding().engine==nullptr,"rowcount/NULLbinding");
        if(!invocation)first=rows;else require(sameRows(first,rows),"restart complete primitive snapshots");
        for(size_t i=0;i<nodes.size();++i){const auto origin=nodes[i]->scanOrigin();std::cout<<"PRIMITIVE_NODE N="<<n<<" invocation="<<invocation<<" node="<<i<<" name="<<nodes[i]->preparedPlanNodeName()<<" stats_cumulative=true inclusive_ms="<<nodes[i]->runtimeMs()<<" rows="<<nodes[i]->runtimeRows()<<" loops="<<nodes[i]->runtimeLoops()<<" origin_engine="<<(origin.engine==&g_engine)<<" origin_db="<<origin.dbname<<" origin_table="<<origin.tablename<<" rid="<<origin.rid<<'\n';}
    }
    for(bool capture:{false,true})helperLane<ExprHelper>(db,n,first,cursor->descriptor(),capture);
    for(bool metadata:{false,true})for(bool capture:{false,true})for(bool binary:{false,true})senderLane(db,n,first,cursor->descriptor(),metadata,capture,binary);
    // Retained actual owning rows survive the genuine graph/owner destruction.
    print("destroy_actual_graph_owner_query",n,4,measured([&]{cursor.reset();execution.reset();query.reset();}));for(size_t i=0;i<first.size();++i)validate(first[i],i+1);
    std::cout<<"PRIMITIVE_EVIDENCE N="<<n<<" invocations=4 rows_each="<<first.size()<<" same_actual_graph=true owning_rows_survive_graph=true descriptor_oids=23,23,25 sizeof_ExprValue="<<sizeof(ExprValue)<<" sizeof_ExprEvalResult="<<sizeof(ExprEvalResult)<<" sizeof_QueryOutputColumn="<<sizeof(QueryOutputColumn)<<" sizeof_PgColumnDescription="<<sizeof(PgColumnDescription)<<'\n';
}
