    Session session;session.username="admin";session.permission=1;session.currentDB=db;session.workMem.assign(16384,false);auto* prior=currentSession();setCurrentSession(&session);size_t completed=0;
    try{DdlExecutor ddl;for(size_t n:{size_t(0),size_t(1),size_t(512)}){const auto table="primitive_n"+std::to_string(n);require(!ddl.executeSql("CREATE TABLE "+table+"(id integer,i integer,t text)",session),"actual table DDL");for(size_t id=1;id<=n;++id)require(g_engine.insertRow(db,table,{{"id",std::to_string(id)},{"i",integer(id)},{"t",text(id)}})==DBStatus::OK,"real heap insert");}for(size_t n:{size_t(0),size_t(1),size_t(512)}){run(db,n);++completed;}require(g_engine.dropDatabase(db)==DBStatus::OK,"drop/lockcleanup");setCurrentSession(prior);std::cout<<"OWNED_PUBLIC_PRIMITIVE_COST_COMPLETE cases="<<completed<<" allocation_build="<<OWNED_PRIMITIVE_COUNT_NEW<<" failures=0\n";return completed==3?0:1;}
