void require(bool value){++checks;if(!value)throw std::runtime_error("public hasFunction/volatility contract differs");}
void validate(const dbms::ExprEvaluator& evaluator){
    for(const auto&entry:functions){
        require(evaluator.hasFunction(entry.name));
        const char actual=evaluator.volatility(entry.name);require(actual==entry.volatility);
        metadataChecksum=metadataChecksum*33+static_cast<unsigned char>(actual);
    }
    for(const auto&entry:keywords){
        require(!evaluator.hasFunction(entry.name));
