template<class Action>Metric measure(Action&&action){
    requests::calls=requests::bytes=0;requests::active=REGISTRY_CONSTRUCTOR_COUNT_NEW;
    const auto wall=stamp(CLOCK_MONOTONIC_RAW),cpu=stamp(CLOCK_PROCESS_CPUTIME_ID),thread=stamp(CLOCK_THREAD_CPUTIME_ID);
    try{action();}catch(...){requests::active=false;throw;}
    Metric m{stamp(CLOCK_MONOTONIC_RAW)-wall,stamp(CLOCK_PROCESS_CPUTIME_ID)-cpu,stamp(CLOCK_THREAD_CPUTIME_ID)-thread,requests::calls,requests::bytes};requests::active=false;return m;
}
